def _parse_attrs(options: Dict[str, Any]) ->Dict[str, Any]:
    attrs = {}
    for key, value in options.items():
        if key == 'align':
            if value in _allowed_aligns:
                attrs[key] = value
        elif key == 'alt':
            attrs[key] = value
        elif key == 'target':
            attrs[key] = value
        elif key in ('width', 'height'):
            # Validate numeric values
            if _num_re.match(value):
                attrs[key] = value
            else:
                # For non-numeric values, store as-is (e.g., "50%" or "auto")
                attrs[key] = value
        elif key in ('class', 'id'):
            attrs[key] = value
        elif key == 'title':
            attrs[key] = value
    return attrs
